{
is_shown_when_inactive = { c:MHG ?= this NOT = { has_variable = ywc_mhg_land_waterway_started } }
possible = { c:MHG ?= this is_country_alive = yes NOT = { has_variable = ywc_mhg_land_waterway_started } country_has_building_group_levels = { type = bg_agriculture value > 0 } }
immediate = { set_variable = { name = ywc_mhg_land_waterway_started value = 1 } set_variable = { name = ywc_mhg_land_stage value = 7200 } set_variable = { name = ywc_mhg_land_pending value = 7200 } set_variable = { name = ywc_mhg_land_captured_income value = yearly_gross_income } change_variable = { name = ywc_mhg_land_captured_income divide = 52 } clamp_variable = { name = ywc_mhg_land_captured_income min = 100 max = 1000000000 } set_variable = { name = ywc_mhg_land_fee value = var:ywc_mhg_land_captured_income } set_variable = { name = ywc_mhg_land_half_fee value = var:ywc_mhg_land_captured_income } change_variable = { name = ywc_mhg_land_half_fee divide = 2 } set_variable = { name = ywc_mhg_land_double_fee value = var:ywc_mhg_land_captured_income } change_variable = { name = ywc_mhg_land_double_fee multiply = 2 } }
on_monthly_pulse = { effect = {
if = { limit = { ywc_mhg_delivery_7200 = yes } trigger_event = { id = ywc_regional.7200 } }
if = { limit = { ywc_mhg_delivery_7201 = yes } trigger_event = { id = ywc_regional.7201 } }
if = { limit = { has_variable = ywc_mhg_land_review_clock NOT = { has_variable = ywc_mhg_land_review_open } NOT = { has_variable = ywc_mhg_land_outcome } is_country_alive = yes } if = { limit = { in_default = no NOT = { has_modifier = declared_bankruptcy } } if = { limit = { var:ywc_mhg_land_registry ?= 1 var:ywc_mhg_dredge_mode ?= 1 } set_variable = { name = ywc_mhg_land_outcome value = 1 } } else = { set_variable = { name = ywc_mhg_land_outcome value = 2 } } } else = { set_variable = { name = ywc_mhg_land_outcome value = 2 } set_variable = { name = ywc_mhg_land_review_missed_payments value = 1 } } remove_variable = ywc_mhg_land_review_clock }
} }
on_complete = { remove_variable = ywc_mhg_land_pending remove_variable = ywc_mhg_land_stage }
on_fail = { remove_variable = ywc_mhg_land_pending remove_variable = ywc_mhg_land_stage }
}

